 r.resumen=readableSummary(r.resumen,metric);
 const journeys={rotacion:['bajas_motivo','bajas_antiguedad','bajas_edad','bajas'],reclutamiento:['contrataciones_desglose','vacantes_proximas','tiempo_contratacion','fuentes_uso','fuentes_seleccion','rechazo_motivo'],relaciones:['negociacion_estatus','incremento_otorgado','incremento_planeado','incremento_meses','incremento_meses_previstos'],ausentismo:['faltas','incapacidades','incapacidades_tipo'],capacitacion:['capacitacion_horas','pregunta_d881d5d2223d'],organizacion:['pregunta_ac42ff684b2c','pregunta_643de8697965','pregunta_d957d87c2bbf','pregunta_51e05c57e7f2'],seguridad:['pregunta_c0790ddf6856','pregunta_1c474db99c5b','pregunta_e2d97d52df60'],beneficios:['costo_transporte','costo_comedor','costo_sgmm'],contexto:['plantilla_operativa','plantilla_administrativa','genero']};
 const tabs=(journeys[view]||candidates.slice(0,5)).filter(m=>candidates.includes(m));
 const canSum=r.resumen.length>0&&r.resumen.every(d=>['personas','eventos','horas'].includes(d.unidad))&&!metric.startsWith('plantilla')&&!(metric==='vacantes_proximas'&&selection('period').length>1);
 $('#content').innerHTML=`<div class="topic-tabs" aria-label="Temas de la sección">${tabs.map(m=>`<button data-metric-tab="${m}" class="${m===metric?'selected':''}" aria-pressed="${m===metric}">${esc(metricName(m))}</button>`).join('')}</div>${view==='reclutamiento'?'<div class="recruit-bridge"><span>Convierte esta información en un seguimiento de puestos.</span><button data-go="planes">Vacantes y plan de acción ↗</button></div>':''}<section class="panel metric-story"><div class="panel-head"><div><p class="eyebrow">${esc(names[view])} · ${selection('period').length} BIMESTRE(S)</p><h2>${esc(metricName(metric))}</h2></div><span class="badge">${fmt(r.total)} celdas de origen</span></div><details class="question-picker"><summary>Elegir otra pregunta del estudio</summary><label for="metric">Todas las preguntas de esta sección</label><select id="metric" class="metric-select">${candidates.map(m=>`<option value="${esc(m)}" ${m===metric?'selected':''}>${esc(metricName(m))}</option>`).join('')}</select></details><div class="visual-toolbar"><p id="statDescription">Mediana de respuestas numéricas válidas. Cada respuesta corresponde a una empresa y un bimestre.</p>${canSum?'<div class="segmented"><button data-stat="mediana" class="selected" aria-pressed="true">Mediana</button><button data-stat="suma" aria-pressed="false">Volumen</button></div>':''}</div><div id="metricVisual">${visualBreakdown(r.resumen)}</div><details class="method-details"><summary>Pregunta original y unidades</summary>${[...new Set(r.definiciones.map(d=>d.pregunta))].map(q=>`<p>${esc(q)}</p>`).join('')}<p>Los intervalos y las respuestas de texto se muestran por separado. Las coberturas pueden variar entre dimensiones; no implican porcentajes de un mismo total.</p></details></section>
 <section class="panel source-panel"><details><summary>Resultados completos por dimensión</summary>${table(['Dimensión','Mediana','Suma compatible','Unidad','Empresas / respuestas','Respuestas de texto'],r.resumen.map(d=>[esc(d.dimension),fmt(d.mediana,2),canSum?fmt(d.suma,2):'No aplica',esc(d.unidad),`${d.n_empresas_respuestas} / ${d.n_respuestas} (${d.n_valores} numéricas)`,Object.entries(d.categorias).map(([k,v])=>`${esc(k)}: ${v}`).join('<br>')]))}</details></section>
 <section class="panel source-panel"><details ${explorerPage>1?'open':''}><summary>Revisar registros y origen <span>${r.total} registros</span></summary><p>Página ${r.pagina} de ${Math.max(1,Math.ceil(r.total/100))}</p>${table(['Empresa','Periodo','Dimensión','Valor','Estado','Hoja / fila / columna',''],r.filas.map(f=>[esc(f.empresa),esc(f.bimestre),esc(f.dimension),f.valor!==null?fmt(f.valor,3):esc(f.texto||'Sin dato'),esc(f.excluido?'Excluido':f.estado),`${esc(f.hoja)} / ${f.fila} / ${f.columna}`,user.rol==='cliente'?'':`<button data-adjust="${f.id}" data-value="${f.valor??''}">Revisar</button>`]))}<div class="inline-actions"><button id="prev" ${explorerPage===1?'disabled':''}>Anterior</button><button id="next" ${explorerPage*100>=r.total?'disabled':''}>Siguiente</button></div></details></section>`;
 $('#metric').onchange=e=>{currentMetric=e.target.value;explorerPage=1;render();};
 document.querySelectorAll('[data-metric-tab]').forEach(b=>b.onclick=()=>{currentMetric=b.dataset.metricTab;explorerPage=1;render();});
 document.querySelectorAll('[data-stat]').forEach(b=>b.onclick=()=>{const stat=b.dataset.stat;$('#metricVisual').innerHTML=visualBreakdown(r.resumen,stat);$('#statDescription').textContent=stat==='suma'?'Suma de respuestas válidas en los bimestres seleccionados. Las coberturas por dimensión pueden diferir.':'Mediana de respuestas numéricas válidas. Cada respuesta corresponde a una empresa y un bimestre.';document.querySelectorAll('[data-stat]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b));});});
 $('#prev').onclick=()=>{explorerPage--;render();};$('#next').onclick=()=>{explorerPage++;render();};bindAdjust();bindNavigation();
