function bindAdjust(){document.querySelectorAll('[data-adjust]').forEach(b=>b.onclick=()=>adjustDialog(Number(b.dataset.adjust),b.dataset.value));}
function adjustDialog(id,value){modal(`<p class="eyebrow">REVISIÓN DE EVIDENCIA</p><h2>Deja una decisión trazable.</h2><p>Un atípico es una señal para revisar la fuente. No se corrige automáticamente.</p><form id="adjustForm"><label>Acción<select name="accion"><option value="excluir">Excluir del cálculo</option><option value="corregir">Corregir valor</option><option value="restaurar">Incluir de nuevo</option></select></label><label>Valor corregido, en la unidad mostrada<input name="valor" type="number" step="any" value="${esc(value)}"></label><label>Motivo y evidencia<textarea name="motivo" minlength="10" maxlength="500" required placeholder="Qué revisaste y por qué procede el cambio"></textarea></label><button class="primary">Guardar en bitácora</button><p id="adjustError" role="alert"></p></form>`);$('#adjustForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{const r=await api(`/hechos/${id}/ajuste`,{method:'POST',body:JSON.stringify({...d,valor:d.valor===''?null:Number(d.valor),revision})});revision=r.revision;$('#dialog').close();await render();}catch(error){$('#adjustError').textContent=error.message;}};}
const issueNames={atipico_plantilla:'Plantilla fuera de lo habitual',plantilla_incompleta:'Plantilla incompleta',plantilla_no_positiva:'Plantilla igual o menor que cero',desglose_incompleto:'Desglose incompleto',desglose_no_concilia:'El desglose no coincide con el total',porcentaje_incompleto:'Porcentajes incompletos',porcentaje_no_suma_100:'Porcentajes que no suman 100',columna_sin_encabezado:'Columna sin pregunta',encabezado_ambiguo:'Encabezado repetido'};
function issueLabel(code){return issueNames[code]||human(code);}
function renderQuality(r){
 revision=r.revision;
 const count=key=>r.conteos[key]||0,total=Object.values(r.conteos).reduce((a,b)=>a+b,0);
 $('#content').innerHTML=`<div class="quality"><article class="card"><p>Valores fuera de lo habitual</p><strong>${fmt(count('atipico_plantilla'))}</strong><small>Señales para contrastar con la fuente</small></article><article class="card"><p>Desgloses por conciliar</p><strong>${fmt(count('desglose_no_concilia'))}</strong><small>Sus partes no coinciden con el total</small></article><article class="card"><p>Observaciones de calidad</p><strong>${fmt(total)}</strong><small>Varias pueden afectar a la misma empresa</small></article></div><section class="panel"><div class="panel-head"><div><p class="eyebrow">ANTES DE TOMAR UNA DECISIÓN</p><h2>¿Cuánto depende la conclusión de este dato?</h2><p>Compara la trayectoria y explora el impacto antes de corregir.</p></div>${user.rol==='cliente'?'':'<button id="audit">Ver bitácora</button>'}</div><label>Qué quieres revisar<select id="issueType"><option value="atipico_plantilla">${issueLabel('atipico_plantilla')}</option>${Object.keys(r.conteos).filter(x=>x!=='atipico_plantilla').map(k=>`<option value="${esc(k)}">${esc(issueLabel(k))}</option>`).join('')}</select></label><div id="issues"></div></section><section class="panel source-panel"><details><summary>Revisar todos los controles de calidad</summary>${table(['Control','Observaciones'],Object.entries(r.conteos).map(([k,v])=>[esc(issueLabel(k)),fmt(v)]))}</details></section><section class="panel source-panel"><details><summary>Qué ocurrió durante la limpieza</summary>${table(['Estado','Celdas'],Object.entries(r.estados).map(([k,v])=>[esc(human(k)),fmt(v)]))}</details></section>`;
 const show=()=>{
  const list=r.incidencias.filter(x=>x.codigo===$('#issueType').value);
  $('#issues').innerHTML=list.slice(0,150).map((x,i)=>`<article class="alert-item"><span class="tag">${esc(issueLabel(x.codigo))}</span><h3>${esc(x.empresa||'Archivo')} · ${esc(x.bimestre?periodLabel(x.bimestre):'')}</h3><p>${esc(x.detalle)}</p>${x.historial?chart(x.historial,'valor','Plantilla operativa (personas)')+`<details><summary>Ver cifras de la trayectoria</summary>${table(['Bimestre','Operativos'],x.historial.map(v=>[esc(periodLabel(v.bimestre)),fmt(v.valor)]))}</details>`:''}<div class="inline-actions">${x.codigo==='atipico_plantilla'?`<button data-impact="${i}">Explorar impacto en rotación</button>`:''}${x.hecho_id&&user.rol!=='cliente'?`<button data-adjust="${x.hecho_id}">Revisar y registrar decisión</button>`:''}</div></article>`).join('')||'<div class="empty-chart">No hay observaciones de este tipo en la selección.</div>';
  if(list.length>150)$('#issues').insertAdjacentHTML('beforeend',`<p>Mostrando 150 de ${list.length}. Acota empresas o periodos para revisar el resto.</p>`);
  bindAdjust();$('#issues').querySelectorAll('[data-impact]').forEach(b=>b.onclick=async()=>{
   b.disabled=true;const item=list[Number(b.dataset.impact)];try{
    const data=await api('/panel?'+query()),s=RHLectura.sensibilidad(data.detalle,item.empresa,item.bimestre);
    modal(`<p class="eyebrow">ANÁLISIS DE SENSIBILIDAD · ${esc(periodLabel(item.bimestre))}</p><h2>La tasa con y sin este registro.</h2><p>Simulación al retirar a ${esc(item.empresa)} del cálculo de este bimestre. No modifica el estudio.</p>${bars([{label:'Con todos los registros válidos',value:s.antes.tasa,note:s.antes.n+' empresas'},{label:'Sin la empresa señalada',value:s.despues.tasa,note:s.despues.n+' empresas'}],'%')}<div class="question">${RHLectura.valid(s.antes.tasa)&&RHLectura.valid(s.despues.tasa)?'Diferencia: '+signed(s.despues.tasa-s.antes.tasa,2)+' puntos porcentuales.':'No hay suficientes registros restantes para calcular la tasa.'} La muestra cambia: este resultado no demuestra que el dato sea incorrecto.</div>${table(['Escenario','Bajas','Plantilla usada','n empresas'],[['Con registro',fmt(s.antes.bajas),fmt(s.antes.denominador),s.antes.n],['Sin registro',fmt(s.despues.bajas),fmt(s.despues.denominador),s.despues.n]])}<p class="muted">Confirma la fuente. La exclusión o corrección definitiva requiere una decisión registrada en la bitácora.</p>`);
   }catch(e){notify(e.message);}finally{b.disabled=false;}
  });
 };$('#issueType').onchange=show;show();
 $('#audit')?.addEventListener('click',async()=>{try{const a=await api('/auditoria');modal('<h2>Bitácora del estudio</h2>'+table(['Fecha','Actor','Acción','Detalle'],a.map(x=>[esc(x.fecha),esc(x.actor),esc(x.accion),esc(JSON.stringify(x.detalle))])));}catch(e){notify(e.message);}});
}
function renderUpload(){
 $('#content').innerHTML=`<section class="panel"><p class="eyebrow">UN ESTUDIO, UNA FUENTE TRAZABLE</p><h2>Del Excel a una lectura clara.</h2><p>Dos filas de encabezado: pregunta y subopción. XLSX con hojas como JUL-AGO_2025, o CSV UTF-8 con ese nombre. Máximo 15 MB.</p><form id="uploadForm"><div id="dropzone" class="dropzone"><h3>Arrastra aquí tu archivo</h3><label>o selecciónalo<input id="file" type="file" accept=".xlsx,.csv" required></label></div><details><summary>Diccionario de columnas editable</summary><p>Descarga el mapeo, modifica sus reglas y adjúntalo antes de revisar el nuevo archivo.</p><a href="/api/diccionario">Descargar diccionario JSON ↗</a><label>Diccionario modificado (opcional)<input id="dictionary" type="file" accept=".json"></label></details><p>Se descartan los campos de contacto. Los valores sin encabezado requieren aclaración en la fuente.</p><button class="primary">Revisar archivo</button></form><div id="preview"></div></section>`;
 const drop=$('#dropzone');drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag');};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');if(e.dataTransfer.files.length)$('#file').files=e.dataTransfer.files;};
 $('#uploadForm').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;button.textContent='Analizando encabezados y datos…';try{const form=new FormData();form.append('archivo',$('#file').files[0]);if($('#dictionary').files[0])form.append('diccionario',await $('#dictionary').files[0].text());const p=await api('/importar/vista-previa',{method:'POST',body:form});$('#preview').innerHTML=`<h2>Vista previa</h2><p>${fmt(p.hechos)} registros normalizados. Revisa las incidencias antes de confirmar.</p>${table(['Hoja','Empresas','Columnas','Filas omitidas','Valores sin encabezado'],p.perfil.map(x=>[esc(x.hoja),x.empresas,x.columnas,x.filas_omitidas,x.sin_encabezado]))}<pre>${esc(JSON.stringify(p.incidencias,null,2))}</pre><p class="question">${esc(p.aviso)}</p><button id="confirmUpload" class="primary">Confirmar y activar este estudio</button>`;$('#confirmUpload').onclick=async ev=>{ev.target.disabled=true;try{await api('/importar/confirmar',{method:'POST',body:JSON.stringify({token:p.token})});await loadFilters();view='calidad';renderNav();await render();notify('Estudio importado. Revisa sus incidencias antes de interpretar resultados.');}catch(err){notify(err.message);ev.target.disabled=false;}};}catch(err){notify(err.message);}finally{button.disabled=false;button.textContent='Revisar archivo';}};
}
function renderUsers(){$('#content').innerHTML=`<section class="panel"><h2>Un acceso para cada responsabilidad.</h2><form id="userForm"><div class="form-row"><label>Usuario<input name="nombre" minlength="3" required></label><label>Contraseña inicial (mínimo 12 caracteres)<input name="password" type="password" minlength="12" autocomplete="new-password" required></label></div><label>Rol<select name="rol"><option value="cliente">Cliente · solo su empresa</option><option value="analista">Analista · estudio completo y correcciones</option><option value="admin">Administrador · incluye gestión de accesos</option></select></label><label>Empresa del cliente<select name="empresa">${filters.empresas.map(x=>`<option value="${esc(x.id)}">${esc(x.nombre)}</option>`).join('')}</select></label><button class="primary">Crear acceso</button></form></section>`;$('#userForm').onsubmit=async e=>{e.preventDefault();try{await api('/usuarios',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});e.target.reset();notify('Acceso creado.');}catch(err){notify(err.message);}};}
function renderScenario(){
 const latest=panel.serie.at(-1);
 $('#content').innerHTML=`<div class="scenario-heading"><p class="eyebrow">ESTUDIO DE DECISIONES</p><h2>¿Cómo quedaría tu equipo?</h2><p>Explora contrataciones y bajas supuestas. El resultado se actualiza al cambiar las cifras.</p></div><div class="grid-two"><section class="panel"><form id="scenario"><div class="form-row"><label>Plantilla de partida<input name="base" type="number" min="0" step="1" value="${latest?.plantilla??0}" required></label><label>Contrataciones planeadas<input name="altas" type="number" min="0" step="1" value="0" required></label><label>Bajas supuestas<input name="bajas" type="number" min="0" step="1" value="0" required></label><label>Costo por contratación (MXN)<input name="costo" type="number" min="0" step="any" value="0" required></label></div><button class="primary">Recalcular escenario</button></form><p class="muted scenario-note">Plantilla inicial: último bimestre seleccionado, ${latest?.n_plantilla??0} empresas. Los cambios en estos campos son supuestos y no se guardan en el estudio.</p></section><section class="panel scenario-output" aria-live="polite"><p class="eyebrow">RESULTADO DEL ESCENARIO</p><div id="scenarioResult"></div></section></div><section class="panel"><div class="panel-head"><div><p class="eyebrow">REFERENCIA A SEIS MESES</p><h3>Si la última rotación se mantuviera…</h3></div></div>${panel.pronostico.disponible?`<div class="persistence-grid">${panel.pronostico.estimaciones.map((v,i)=>`<div><span>Dentro de ${(i+1)*2} meses</span><strong>${fmt(v,2)} %</strong><small>Persistencia del último valor</small></div>`).join('')}</div><details><summary>Qué tan limitada es esta referencia</summary><p>Error medio retrospectivo: ${fmt(panel.pronostico.mae_backtest_pp,2)} puntos porcentuales, sobre ${panel.pronostico.n_backtest} comparaciones de un paso.</p><p>${esc(panel.pronostico.advertencia)}</p></details>`:`<p class="muted">${esc(panel.pronostico.motivo)}</p>`}<p class="sample-note">Este escenario no estima el efecto de una política salarial ni predice comportamientos individuales.</p></section>`;
 const calculate=()=>{
  const form=$('#scenario');if(!form.checkValidity()){$('#scenarioResult').textContent='Completa los cuatro campos con cantidades válidas.';return;}
  const d=Object.fromEntries([...new FormData(form)].map(([k,v])=>[k,Number(v)])),final=d.base+d.altas-d.bajas;
  if(final<0){$('#scenarioResult').textContent='Las bajas supuestas superan la plantilla y las contrataciones. Revisa las cifras.';return;}
  $('#scenarioResult').innerHTML=`<strong class="scenario-total">${fmt(final)}</strong><p>personas al cierre supuesto</p><div class="scenario-equation"><span>${fmt(d.base)}<small>Base</small></span><span>+</span><span>${fmt(d.altas)}<small>Altas</small></span><span>−</span><span>${fmt(d.bajas)}<small>Bajas</small></span></div>${bars([{label:'Plantilla inicial',value:d.base},{label:'Plantilla del escenario',value:final}],'personas')}<div class="scenario-cost"><span>Costo supuesto de contratación</span><strong>$${fmt(d.altas*d.costo,2)} MXN</strong></div>`;
 };
 $('#scenario').oninput=calculate;$('#scenario').onsubmit=e=>{e.preventDefault();calculate();};calculate();
}
$('#story').onclick=async()=>{try{
 if(!selection('company').length||!selection('period').length)return notify('Selecciona una empresa y un bimestre.');
 const p=await api('/panel?'+query()),slides=priorities(p);if(!slides.length)return notify('Carga un estudio para iniciar la presentación.');
 let i=0;const draw=()=>{const s=slides[i];$('#dialogContent').innerHTML=`<p class="story-number">CATCH · CONVERSACIÓN ${i+1} DE ${slides.length}</p><h2 class="story-title">${s.title}</h2><div class="story-metric">${s.value}</div><p>${s.unit}</p><p class="question">${s.text}</p><div class="inline-actions"><button id="storyPrev" ${i===0?'disabled':''}>Anterior</button><button id="storyNext" ${i===slides.length-1?'disabled':''}>Siguiente</button><button id="storyEvidence" class="primary">${s.action} ↗</button></div>`;$('#storyPrev').onclick=()=>{i--;draw();};$('#storyNext').onclick=()=>{i++;draw();};$('#storyEvidence').onclick=()=>{$('#dialog').close();navigate(s.go,s.metric);};};
 $('#dialog').showModal();draw();
 }catch(e){notify(e.message);}};
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();if($('#question'))$('#question').focus();else{view='inicio';renderNav();render().then(()=>$('#question')?.focus());}}});
boot().catch(()=>showLogin());
